import datetime,json,os,statistics,subprocess
from pathlib import Path
p=Path(__file__).parent;q=p.parent/'integer-decimal-cast-2cc3024'
variants=json.loads((p/'variants.json').read_text());ids=['div_i16_literal_ansifalse','div_integer_ansitrue']
checks={r['id']:r for r in json.loads((q/'after-subquery-check.json').read_text())['results']}
base=os.environ.copy();assert not any(k.startswith(('MALLOC_','GLIBC_','LD_PRELOAD','DECIMAL_BENCH_')) for k in base)
root=p/'explore';root.mkdir(exist_ok=False);runs=[]
keys=list(variants);orders=[keys,keys[::-1],keys[3:]+keys[:3],(keys[3:]+keys[:3])[::-1]]
for round_no,order in enumerate(orders):
 for v in order:
  for case in ids[round_no%2:]+ids[:round_no%2]:
   out=root/f'{round_no:02}-{v}-{case}';out.mkdir()
   for name in ['control','ack']:os.mkfifo(out/name)
   cmd=['perf','stat','--delay=-1',f'--control=fifo:{out}/control,{out}/ack','--json-output','-o',str(out/'counters.jsonl'),'-e','{instructions:u,cycles:u},task-clock:u,context-switches:u,cpu-migrations:u,page-faults:u','--','taskset','-c','2',str(q/'after-bench'),str(out/'capture.json'),'subqueries',case]
   started=datetime.datetime.now(datetime.UTC).isoformat();r=subprocess.run(cmd,env=base|variants[v]|{'DECIMAL_BENCH_PERF_DIR':str(out),'DECIMAL_BENCH_PERF_PHASE':'execution'},capture_output=True,text=True,check=True,timeout=120)
   cap=json.loads((out/'capture.json').read_text());assert len(cap['results'])==1;row=cap['results'][0]
   for k,value in checks[case].items():assert row[k]==value,(v,case,k)
   counters=[json.loads(x) for x in (out/'counters.jsonl').read_text().splitlines() if x.startswith('{')]
   assert len(counters)==6 and all(x['pcnt-running']==100 for x in counters)
   assert r.stderr.count('Events enabled')==1 and len(row['samples_ms'])==9
   c={x['event']:float(x['counter-value']) for x in counters}
   run={'variant':v,'round':round_no,'case':case,'started_utc':started,'environment':variants[v],'command':cmd,'capture':cap,'counters':counters,'stderr':r.stderr,'median_ms':statistics.median(row['samples_ms']),'page_faults':c['page-faults:u']};runs.append(run)
   print(round_no,v,case,round(run['median_ms'],3),run['page_faults'],flush=True)
   (p/'explore.json').write_text(json.dumps({'orders':orders,'cases':ids,'runs':runs},indent=2)+'\n')
for case in ids:
 for v in variants:
  x=[r for r in runs if r['case']==case and r['variant']==v]
  print('SUMMARY',case,v,'median',statistics.median(r['median_ms'] for r in x),'faults',[r['page_faults'] for r in x],flush=True)

