import datetime,json,os,selectors,statistics,subprocess,time
from pathlib import Path
p=Path(__file__).parent;q=p.parent/'integer-decimal-cast-2cc3024';root=p/'memory';root.mkdir(exist_ok=False)
all_variants=json.loads((p/'variants.json').read_text());variants={k:all_variants[k] for k in ['default','both_1m','tcache_256k']}
ids=['div_i16_literal_ansifalse','div_integer_ansitrue','div_i32_column_ansitrue','no_division_ansifalse','div_decimal_ansitrue','plain_projection_ansifalse','round_decimal_ansifalse','correlated_max_ansifalse']
checks={r['id']:r for r in json.loads((q/'after-subquery-check.json').read_text())['results']};assert set(ids)<=checks.keys(),set(ids)-checks.keys()
base=os.environ.copy();assert not any(k.startswith(('MALLOC_','GLIBC_','LD_PRELOAD','DECIMAL_BENCH_')) for k in base)
def snapshot(pid):
 proc=Path('/proc')/str(pid);status=(proc/'status').read_text();smaps=(proc/'smaps_rollup').read_text();stat=(proc/'stat').read_text();fields=stat[stat.rindex(')')+2:].split()
 def memory_fields(text):
  return {line.split(':',1)[0]:int(line.split()[1]) for line in text.splitlines() if line.endswith(' kB')}
 return {'status':status,'smaps_rollup':smaps,'status_kib':memory_fields(status),'smaps_kib':memory_fields(smaps),'minor_faults':int(fields[7]),'major_faults':int(fields[9]),'monotonic_ns':time.monotonic_ns()}
runs=[]
for round_no in range(4):
 keys=list(variants);offset=round_no%len(keys);order=keys[offset:]+keys[:offset]
 if round_no%2:order.reverse()
 for v in order:
  for case in ids[round_no:]+ids[:round_no]:
   out=root/f'{round_no:02}-{v}-{case}';out.mkdir();fds=[];proc=None
   try:
    for name in ['control','ack']:
     os.mkfifo(out/name);fds.append(os.open(out/name,os.O_RDWR|os.O_NONBLOCK))
    with selectors.DefaultSelector() as selector,(out/'stderr.txt').open('w') as stderr:
     selector.register(fds[0],selectors.EVENT_READ)
     cmd=['taskset','-c','2',str(q/'after-bench'),str(out/'capture.json'),'subqueries',case]
     started=datetime.datetime.now(datetime.UTC).isoformat();proc=subprocess.Popen(cmd,env=base|variants[v]|{'DECIMAL_BENCH_PERF_DIR':str(out),'DECIMAL_BENCH_PERF_PHASE':'execution'},stdout=subprocess.DEVNULL,stderr=stderr)
     deadline=time.monotonic()+60;snapshots={}
     while len(snapshots)<2:
      assert time.monotonic()<deadline,('timeout',v,case)
      assert proc.poll() is None,('early exit',v,case,(out/'stderr.txt').read_text())
      if not selector.select(timeout=.1):continue
      command=os.read(fds[0],4096).decode();expected='enable\n' if not snapshots else 'disable\n';assert command==expected,(command,expected)
      snapshots[command.strip()]=snapshot(proc.pid)
      os.write(fds[1],b'ack\n')
     assert proc.wait(timeout=60)==0,(out/'stderr.txt').read_text()
    cap=json.loads((out/'capture.json').read_text());assert len(cap['results'])==1;row=cap['results'][0]
    for k,value in checks[case].items():assert row[k]==value,(v,case,k)
    before=snapshots['enable'];after=snapshots['disable']
    record={'variant':v,'round':round_no,'case':case,'environment':variants[v],'started_utc':started,'command':cmd,'capture':cap,'snapshots':snapshots,'median_ms_with_memory_probe':statistics.median(row['samples_ms']),'minor_faults':after['minor_faults']-before['minor_faults'],'rss_before_kib':before['smaps_kib']['Rss'],'rss_after_kib':after['smaps_kib']['Rss'],'private_dirty_after_kib':after['smaps_kib']['Private_Dirty'],'rss_delta_kib':after['smaps_kib']['Rss']-before['smaps_kib']['Rss'],'peak_rss_after_kib':after['status_kib']['VmHWM']};runs.append(record)
    print(round_no,v,case,'RSS KiB',record['rss_before_kib'],record['rss_after_kib'],'faults',record['minor_faults'],flush=True)
    (p/'memory.json').write_text(json.dumps({'scope':'Child is paused on existing FIFO handshake before and after nine executions. smaps_rollup Rss/Private_Dirty are live measurements; VmHWM includes startup and validation. Context, input tables and plans remain alive after execution. Parent snapshots are outside child elapsed samples, but all timings here are excluded from the perf comparison.','variants':variants,'cases':ids,'runs':runs},indent=2)+'\n')
   finally:
    if proc is not None and proc.poll() is None:proc.kill();proc.wait()
    for fd in fds:os.close(fd)
print('All memory probes passed',flush=True)

