import json,statistics
from pathlib import Path
p=Path(__file__).parent;summary={}
for name in ['wrapped','native']:
 data=json.loads((p/f'performance-{name}.json').read_text());summary[name]={}
 for case in data['cases']:
  item={}
  for variant in data['variants']:
   runs=[r for r in data['runs'] if r['case']==case and r['variant']==variant];times=[r['median_ms'] for r in runs]
   counters={key:[float(next(c['counter-value'] for c in r['counters'] if c['event']==key)) for r in runs] for key in ['instructions:u','cycles:u','task-clock:u','context-switches:u','cpu-migrations:u','page-faults:u']}
   item[variant]={'processes':len(runs),'median_ms':statistics.median(times),'mean_ms':statistics.mean(times),'range_ms':[min(times),max(times)],'median_counters':{k:statistics.median(v) for k,v in counters.items()},'range_counters':{k:[min(v),max(v)] for k,v in counters.items()}}
   if case in ['div_i16_literal_ansifalse','div_integer_ansitrue']:
    item[variant]['fault_groups']={}
    for group in ['low','high']:
     subset=[r for r in runs if (r['page_faults']>1000)==(group=='high')]
     item[variant]['fault_groups'][group]={'processes':len(subset),'median_ms':statistics.median(r['median_ms'] for r in subset) if subset else None,'range_ms':[min(r['median_ms'] for r in subset),max(r['median_ms'] for r in subset)] if subset else None}
  for variant in data['variants']:
   if variant!='default':
    item[variant]['change_percent']={key:100*(item[variant][key]/item['default'][key]-1) for key in ['median_ms','mean_ms']}
    item[variant]['change_percent']['instructions']=100*(item[variant]['median_counters']['instructions:u']/item['default']['median_counters']['instructions:u']-1)
  summary[name][case]=item
memory=json.loads((p/'memory.json').read_text());summary['memory']={}
for case in memory['cases']:
 item={}
 for variant in memory['variants']:
  runs=[r for r in memory['runs'] if r['case']==case and r['variant']==variant]
  item[variant]={'processes':len(runs),'median':{field:statistics.median(r[field] for r in runs) for field in ['rss_before_kib','rss_after_kib','private_dirty_after_kib','peak_rss_after_kib','rss_delta_kib','minor_faults']},'range':{field:[min(r[field] for r in runs),max(r[field] for r in runs)] for field in ['rss_after_kib','private_dirty_after_kib','peak_rss_after_kib']}}
 for variant in memory['variants']:
  if variant!='default':item[variant]['difference_kib']={key:item[variant]['median'][key]-item['default']['median'][key] for key in ['rss_after_kib','private_dirty_after_kib','peak_rss_after_kib']}
 summary['memory'][case]=item
(p/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
for name in ['wrapped','native']:
 print(name)
 for case,variants in summary[name].items():
  print(case,[(v,round(x['median_ms'],4),[round(y,4) for y in x['range_ms']],x.get('fault_groups'),x.get('change_percent')) for v,x in variants.items()])
print('Memory private dirty difference KiB')
for case,variants in summary['memory'].items():print(case,{v:x.get('difference_kib') for v,x in variants.items()})
